UPDATE `broadcast_text` SET `Text` = 'Don''t be shy, buy a round for everyone!' WHERE `Id` = 10176;
UPDATE `broadcast_text` SET `Text` = 'Tips are always graciously accepted, friend.' WHERE `Id` = 10177;
UPDATE `broadcast_text` SET `Text` = 'Just in... another batch of Darkmoon Special Reserve.  Come get yours before they''re all gone!' WHERE `Id` = 10178;
UPDATE `broadcast_text` SET `Text` = 'Come to learn, eh? Well I just might have some work for you, scrub.' WHERE `Id` = 10191;
