UPDATE `broadcast_text` SET `Text` = 'I bet my friend Gruk would like this rock for the spear he is making! It''s very sharp... I hope he likes it.' WHERE `Id` = 10280;
UPDATE `broadcast_text` SET `Text` = 'There... That should be enough rocks to make a necklace. I should probably get home now anyway.' WHERE `Id` = 10281;
UPDATE `broadcast_text` SET `Text` = 'Yummy. I love roasted Plainstrider.' WHERE `Id` = 10292;
