UPDATE `broadcast_text` SET `Text` = 'Alrighty then, $n, here we go: one illusory-enhanced, Warsong orc disguise, complete with Smell-A-Vision!' WHERE `Id` = 24752;
UPDATE `broadcast_text` SET `Text` = 'The mist is death... senseless, without compassion.' WHERE `Id` = 24757;
UPDATE `broadcast_text` SET `Text` = 'These cages are bled dry. Get me more prisoners at once!' WHERE `Id` = 24794;
UPDATE `broadcast_text` SET `Text` = 'These prisons are to be filled at once or Malygos will know why!' WHERE `Id` = 24795;
UPDATE `broadcast_text` SET `Text` = 'Bring me more prisoners! Do not rest until Azeroth has been cleansed of its reckless magic-users!' WHERE `Id` = 24796;
UPDATE `broadcast_text` SET `Text` = 'Fill these prisons with mages! Malygos demands it!' WHERE `Id` = 24797;
UPDATE `broadcast_text` SET `Text` = 'The ancestors knew a way to confound an enemy''s senses. We could use this knowledge to discover the Scourge''s weakness or strike at their commanders. Without their leaders, the Scourge would fall before our warriors.' WHERE `Id` = 24800;
UPDATE `broadcast_text` SET `Text` = 'Speak slowly, child, I am new to your strange tongue.' WHERE `Id` = 24804;
