UPDATE `broadcast_text` SET `Text` = 'Skar''this has informed us well. We have worked our way into the slave pens and await your cryomancerss.' WHERE `Id` = 25127;
UPDATE `broadcast_text` SET `Text` = 'The ritual in Coilfang will bring Ahune through once he is fully prepared, and the resulting clash between Firelord and Frostlord will rend the foundations of this world. Our ultimate goals are in reach at last....' WHERE `Id` = 25128;
UPDATE `broadcast_text` SET `Text` = 'I serve only the master now.' WHERE `Id` = 25195;
