UPDATE `broadcast_text` SET `Text` = 'Now, $n, let us release their souls and hear what they have to say.' WHERE `Id` = 25204;
UPDATE `broadcast_text` SET `Text` = 'This is dire news indeed!' WHERE `Id` = 25211;
UPDATE `broadcast_text` SET `Text` = 'I''ll be damned if these blasted Scourge are going to drive us away!  Us settlers gave everything up to start new lives in Northrend.$B$BYou''d better believe we''re going to fight tooth and nail.' WHERE `Id` = 25212;
UPDATE `broadcast_text` SET `Text` = 'Hold, friends! There is information to be had before this devil meets his fate!' WHERE `Id` = 25221;
UPDATE `broadcast_text` SET `Text` = 'Where is Anveena, demon? What has become of Kalec?' WHERE `Id` = 25226;
UPDATE `broadcast_text` SET `Text` = 'You will tell me where they are!' WHERE `Id` = 25227;
UPDATE `broadcast_text` SET `Text` = 'Speak! I grow weary of asking! ' WHERE `Id` = 25228;
UPDATE `broadcast_text` SET `Text` = 'Malygos, my lord... I did my... best.' WHERE `Id` = 25229;
UPDATE `broadcast_text` SET `Text` = 'The Agamath Gate has been breached!' WHERE `Id` = 25232;
UPDATE `broadcast_text` SET `Text` = 'The Rohendor Gate has been shattered! Move forward, champions!' WHERE `Id` = 25233;
UPDATE `broadcast_text` SET `Text` = 'The Archonisus Gate is no more! The way to the Sunwell is clear!' WHERE `Id` = 25234;
UPDATE `broadcast_text` SET `Text` = 'Arthas was once a human prince.  The army he led into Northrend suffered a horrible fate.$B$BMy brother, Thassarian, was a part of that army.' WHERE `Id` = 25264;
UPDATE `broadcast_text` SET `Text` = 'I''m very busy right now, $r. Please leave me alone.' WHERE `Id` = 25316;
