UPDATE `broadcast_text` SET `Text` = 'Don''t let me down again, $n. Make sure this evacuee reaches safety.' WHERE `Id` = 25320;
UPDATE `broadcast_text` SET `Text` = 'It is truly a pleasure to see you again, $n.' WHERE `Id` = 25394;
UPDATE `broadcast_text` SET `Text` = 'Our arrogance was unpardonable. We damned one of the most noble beings of all. We may never atone for this sin.' WHERE `Id` = 25408;
UPDATE `broadcast_text` SET `Text` = 'Can it be?' WHERE `Id` = 25410;
UPDATE `broadcast_text` SET `Text` = 'Blessed ancestors! I feel it... so much love... so much grace... there are... no words... impossible to describe...' WHERE `Id` = 25413;
UPDATE `broadcast_text` SET `Text` = 'Annihilate them.' WHERE `Id` = 25430;
UPDATE `broadcast_text` SET `Text` = 'Not what I had... planned.' WHERE `Id` = 25431;
UPDATE `broadcast_text` SET `Text` = 'Oh, the horror!' WHERE `Id` = 25432;
UPDATE `broadcast_text` SET `Text` = 'Well aren''t you lucky?' WHERE `Id` = 25433;
UPDATE `broadcast_text` SET `Text` = 'Now I''m getting annoyed.' WHERE `Id` = 25434;
UPDATE `broadcast_text` SET `Text` = 'Lackeys be damned! I''ll finish you myself!' WHERE `Id` = 25435;
