UPDATE `broadcast_text` SET `Text` = 'Farewell, Raelorasz.' WHERE `Id` = 25472;
UPDATE `broadcast_text` SET `Text` = 'Stay close to me, $n. I could not bear for any harm to come to you.' WHERE `Id` = 25474;
