UPDATE `broadcast_text` SET `Text` = 'I''m sorry, Arthas. I can''t watch you do this.' WHERE `Id` = 27330;
UPDATE `broadcast_text` SET `Text` = 'Enjoy the ride! It''s a one way trip!' WHERE `Id` = 27337;
