UPDATE `broadcast_text` SET `Text` = 'I ain''t ''fraid of no ghost!' WHERE `Id` = 35836;
UPDATE `broadcast_text` SET `Text` = 'Surveyor? I hardly know her! Hah HAH!' WHERE `Id` = 35837;
UPDATE `broadcast_text` SET `Text` = 'Don''t botch this - I''m angling for Sr. Grade by the end of the year.' WHERE `Id` = 35838;
UPDATE `broadcast_text` SET `Text` = 'Let''s do this thing.' WHERE `Id` = 35839;
UPDATE `broadcast_text` SET `Text` = 'Watch my back, I need to concentrate on this...' WHERE `Id` = 35846;
UPDATE `broadcast_text` SET `Text` = 'There''s the survey marker!' WHERE `Id` = 35847;
UPDATE `broadcast_text` SET `Text` = 'Here we go - keep those things off of me while I work!' WHERE `Id` = 35848;
UPDATE `broadcast_text` SET `Text` = 'I got it!' WHERE `Id` = 35849;
UPDATE `broadcast_text` SET `Text` = 'That''s how it''s done!' WHERE `Id` = 35862;
UPDATE `broadcast_text` SET `Text` = 'I''ll never make Sr. Grade at this rate...' WHERE `Id` = 35863;
UPDATE `broadcast_text` SET `Text` = 'I''m going to put in for hazard pay.' WHERE `Id` = 35864;
UPDATE `broadcast_text` SET `Text` = '...and stay dead!' WHERE `Id` = 35865;
