UPDATE `broadcast_text` SET `Text` = 'Damnation!' WHERE `Id` = 38014;
UPDATE `broadcast_text` SET `Text` = 'Doomed for eternity!' WHERE `Id` = 38016;
UPDATE `broadcast_text` SET `Text` = 'The swell of souls will not be abated! You only delay the inevitable.' WHERE `Id` = 38018;
UPDATE `broadcast_text` SET `Text` = 'Stare into the abyss and see your end.' WHERE `Id` = 38020;
