UPDATE `broadcast_text` SET `Text` = 'Thank you! I could not have held out for much longer.... A terrible thing has happened here.' WHERE `Id` = 40599;
UPDATE `broadcast_text` SET `Text` = 'We believed the Sanctum was well-fortified, but we were not prepared for the nature of this assault.' WHERE `Id` = 40600;
