UPDATE `broadcast_text` SET `Text` = 'I know not the extent of their plans, heroes, but I know this:  They cannot be allowed to succeed!' WHERE `Id` = 40606;
UPDATE `broadcast_text` SET `Text` = 'You always secretly thought I looked fat!' WHERE `Id` = 40619;
