UPDATE `broadcast_text` SET `Text` = 'You told him I was fat behind my back, didn''t you?!' WHERE `Id` = 40624;
UPDATE `broadcast_text` SET `Text` = 'You''re just jealous I found a man with skills AND a fat wallet.' WHERE `Id` = 40625;
UPDATE `broadcast_text` SET `Text` = 'You can never replace me. Chip will never stoop to dating someone who makes a brute look attractive!' WHERE `Id` = 40626;
