UPDATE `broadcast_text` SET `Text` = 'Hello, $c!$B$BThese poor creatures are giving everything they have to fight the minions of the Twilight''s Hammer in this dark place.$B$BI''ve done my best to revive those that have fallen.$B$BIf you need an additional mount, these birds are ready to take wing again. Treat them well!' WHERE `Id` = 40663;
UPDATE `broadcast_text` SET `Text` = 'You''ve gotten in my way one too many times, gnome.' WHERE `Id` = 40668;
UPDATE `broadcast_text` SET `Text` = 'You have fully depleted my patience as well.' WHERE `Id` = 40669;
UPDATE `broadcast_text` SET `Text` = 'There isn''t room in this town for both of us!' WHERE `Id` = 40670;
