UPDATE `broadcast_text` SET `Text` = 'Urk... no...' WHERE `Id` = 40678;
UPDATE `broadcast_text` SET `Text` = 'You can be sure to tell Gallywix not to underestimate Gnomeregan anymore.' WHERE `Id` = 40687;
UPDATE `broadcast_text` SET `Text` = 'Until next time, Megs. Don''t forget today''s lesson.' WHERE `Id` = 40688;
UPDATE `broadcast_text` SET `Text` = 'And now all your goblin friends are safe and happy again and there''s no more pirates to blow up your ships!' WHERE `Id` = 40713;
UPDATE `broadcast_text` SET `Text` = 'Well gosh, I''m so flattered! I''d love to! You hang on just a giggle, now...' WHERE `Id` = 40714;
