UPDATE `broadcast_text` SET `Text` = 'Judgment day is soon upon us, Helix.' WHERE `Id` = 42541;
UPDATE `broadcast_text` SET `Text` = 'Call for the people. I wish to speak to them one last time before the dawning.' WHERE `Id` = 42542;
UPDATE `broadcast_text` SET `Text` = 'Aye. Tonight.' WHERE `Id` = 42544;
UPDATE `broadcast_text` SET `Text` = 'To me, my minions! Strike now!' WHERE `Id` = 42545;
UPDATE `broadcast_text` SET `Text` = 'Do not relent! He is weakening!' WHERE `Id` = 42546;
UPDATE `broadcast_text` SET `Text` = 'The rally is about to begin!' WHERE `Id` = 42569;
UPDATE `broadcast_text` SET `Text` = 'Gather, brothers and sisters! Come, all, and listen!' WHERE `Id` = 42570;
UPDATE `broadcast_text` SET `Text` = 'Brothers. Sisters. We are ABANDONED - the orphaned children of Stormwind.' WHERE `Id` = 42571;
UPDATE `broadcast_text` SET `Text` = 'Our "king" sits atop his throne made of gold and shrugs at our plight!' WHERE `Id` = 42572;
UPDATE `broadcast_text` SET `Text` = 'Meanwhile, our children die of starvation on these very streets!' WHERE `Id` = 42573;
UPDATE `broadcast_text` SET `Text` = 'HIS war, not ours, cost us our livelihood. WE paid for the Alliance''s victories with our blood and the blood of our loved ones!' WHERE `Id` = 42574;
UPDATE `broadcast_text` SET `Text` = 'The time has come, brothers and sisters, to stop this injustice!' WHERE `Id` = 42575;
UPDATE `broadcast_text` SET `Text` = 'The government of Stormwind, of the ALLIANCE, must be made accountable for what it has done to us!' WHERE `Id` = 42576;
UPDATE `broadcast_text` SET `Text` = 'Today, we are reborn! Today, we take a stand as men and women, not nameless, faceless numbers!' WHERE `Id` = 42577;
UPDATE `broadcast_text` SET `Text` = 'We have secured the Hunter''s Rise! All invaders have been repelled and the evacuation has been completed!' WHERE `Id` = 42591;
UPDATE `broadcast_text` SET `Text` = 'Daddy...' WHERE `Id` = 42604;
