UPDATE `broadcast_text` SET `Text` = 'RISE UP BROTHERHOOD! THE DAWNING DAY IS UPON US!' WHERE `Id` = 42660;
UPDATE `broadcast_text` SET `Text` = 'Tie them up.' WHERE `Id` = 42661;
