UPDATE `broadcast_text` SET `Text` = 'Leave nothing but ashes in your wake, brothers! Burn Sentinel Hill to the ground!' WHERE `Id` = 42672;
UPDATE `broadcast_text` SET `Text` = 'And you, $n, I will spare your life. You have done much to help our cause, albeit unwittingly, but the next time we meet it will be as enemies. ' WHERE `Id` = 42673;
