UPDATE `broadcast_text` SET `Text` = 'Gaze to the heavens! What do you see?' WHERE `Id` = 44772;
UPDATE `broadcast_text` SET `Text` = 'The glimmer of your life, extinguished.' WHERE `Id` = 44773;
UPDATE `broadcast_text` SET `Text` = 'Insignificant!' WHERE `Id` = 44774;
