UPDATE `broadcast_text` SET `Text` = 'Your presence is not welcome here, Amnennar.' WHERE `Id` = 44920;
UPDATE `broadcast_text` SET `Text` = 'What brings you inside these cursed lands?' WHERE `Id` = 44922;
UPDATE `broadcast_text` SET `Text` = 'How do you do, $n?' WHERE `Id` = 44945;
UPDATE `broadcast_text` SET `Text` = 'We haven''t got much time. Crowley will be arriving shortly. Let''s go!' WHERE `Id` = 44951;
