UPDATE `broadcast_text` SET `Text` = 'Good evening.' WHERE `Id` = 48949;
UPDATE `broadcast_text` SET `Text` = 'I hope my people have been welcoming to you. These are burdened times, so I fear much may be competing with their good graces.' WHERE `Id` = 48950;
