UPDATE `broadcast_text` SET `Text` = 'There is trouble at Lor''danel, a village of ours across the waters from Rut''theran.' WHERE `Id` = 48953;
UPDATE `broadcast_text` SET `Text` = 'If any of your people can be spared, I fear war encroaching upon us in Kalimdor.' WHERE `Id` = 48954;
UPDATE `broadcast_text` SET `Text` = 'Priestess Tyrande! We did not expect you. Good evening.' WHERE `Id` = 48957;
UPDATE `broadcast_text` SET `Text` = 'We will take our leave. Again, welcome to all of you.' WHERE `Id` = 48958;
UPDATE `broadcast_text` SET `Text` = 'You are mine!' WHERE `Id` = 48962;
