UPDATE `broadcast_text` SET `Text` = 'All you gotta do is let me teach you how to do an Eviscerate. Then, head over to one of those training dummies that Bamm is shooting at and attack it with a Sinister Strike. Once you''ve done that, finish it off with the Eviscerate.' WHERE `Id` = 49031;
UPDATE `broadcast_text` SET `Text` = 'I''ll set the cap to auto-activate once you''re at the villa. Just make sure you avoid those pigs!' WHERE `Id` = 49035;
