UPDATE `broadcast_text` SET `Text` = 'I don''t talk to no $g scrub : trash;!' WHERE `Id` = 49175;
UPDATE `broadcast_text` SET `Text` = 'You''re not quite in my league, honey.' WHERE `Id` = 49176;
UPDATE `broadcast_text` SET `Text` = 'I didn''t talk to you back in school and I''m sure not going to start now.' WHERE `Id` = 49177;
UPDATE `broadcast_text` SET `Text` = 'That''s an interesting... "outfit" you''re wearing.' WHERE `Id` = 49178;
UPDATE `broadcast_text` SET `Text` = 'Yes. I''d love a refill. Fetch one and be quick about it.' WHERE `Id` = 49179;
UPDATE `broadcast_text` SET `Text` = 'This is the Trade Prince''s party, sweetie. Invite only!' WHERE `Id` = 49180;
UPDATE `broadcast_text` SET `Text` = '$n, right? Word of advice: don''t let the Trade Prince catch you around here. He knows you''re after his job.$B$BEveryone knows.' WHERE `Id` = 49181;
UPDATE `broadcast_text` SET `Text` = 'A mook?! I don''t speak to brutes. How dare you!' WHERE `Id` = 49182;
UPDATE `broadcast_text` SET `Text` = 'What are we calling you things these days? Brutes? Hobgoblins?$B$BI can''t keep it straight. Get out of here.' WHERE `Id` = 49183;
UPDATE `broadcast_text` SET `Text` = 'You''re big and strong. But you need a bath. Go jump in the pool.' WHERE `Id` = 49184;
UPDATE `broadcast_text` SET `Text` = 'Oh no you did not just talk to me!' WHERE `Id` = 49185;
UPDATE `broadcast_text` SET `Text` = 'What smells around here? Oh, that''d be you.$B$BBeat it!' WHERE `Id` = 49186;
UPDATE `broadcast_text` SET `Text` = 'What''s your name?$B$BI guess it''s a good thing you brutes can''t talk. Otherwise, I''d have to tell the Trade Prince how you annoyed me.$B$BNow scram!' WHERE `Id` = 49187;
UPDATE `broadcast_text` SET `Text` = 'Touch me one more time and I''ll make sure that they send you to the Undermine!' WHERE `Id` = 49188;
