UPDATE `broadcast_text` SET `Text` = 'I do.' WHERE `Id` = 49215;
UPDATE `broadcast_text` SET `Text` = 'Don''t worry about Hobart, boss. He''s just having a bit of a breakdown right now.$B$BThe Cataclysm couldn''t have come at a worse time for him. He was so close to being done with the Micro Mechachicken.' WHERE `Id` = 49240;
UPDATE `broadcast_text` SET `Text` = 'I''m on it, doctor. Schematics, check. Toothbrush, check.' WHERE `Id` = 49241;
