UPDATE `broadcast_text` SET `Text` = 'I''ve been waiting a long time for this, you know.' WHERE `Id` = 49477;
UPDATE `broadcast_text` SET `Text` = 'Biding my time, building my forces, studying the minds of my enemies.' WHERE `Id` = 49478;
UPDATE `broadcast_text` SET `Text` = 'I was never very good at hand-to-hand combat, you know.  Not like my father.' WHERE `Id` = 49479;
