UPDATE `broadcast_text` SET `Text` = 'Congratulations, adventurer.' WHERE `Id` = 49640;
UPDATE `broadcast_text` SET `Text` = 'You''ve managed to walk right into my trap!' WHERE `Id` = 49642;
UPDATE `broadcast_text` SET `Text` = 'A note falls to the floor!' WHERE `Id` = 49658;
