UPDATE `broadcast_text` SET `Text` = 'They are surely unredeemable, but it still hurts to see them die.' WHERE `Id` = 49670;
UPDATE `broadcast_text` SET `Text` = 'My dear friends... I''m so sorry...' WHERE `Id` = 49671;
UPDATE `broadcast_text` SET `Text` = 'His body screams for death, but his soul screams for mercy.' WHERE `Id` = 49672;
UPDATE `broadcast_text` SET `Text` = 'The corruption goes much further than these spiders. I fear the true source is not within this cave.' WHERE `Id` = 49673;
