UPDATE `broadcast_text` SET `Text` = 'Corruption this deep could not have come from outside.' WHERE `Id` = 49675;
UPDATE `broadcast_text` SET `Text` = 'It almost seems as if he was born with this corruption inside of him.' WHERE `Id` = 49676;
UPDATE `broadcast_text` SET `Text` = 'I have no further training for you.  Continue east, to the Menders'' Stead, for now.  You will be summoned when the Battle for Andorhal commences.  Hopefully Koltira doesn''t wait too long...' WHERE `Id` = 49677;
UPDATE `broadcast_text` SET `Text` = 'I fear time may not be on our side, Ilthalaine. The battle may carry to Teldrassil itself if we do not act soon.' WHERE `Id` = 49682;
