UPDATE `broadcast_text` SET `Text` = 'Study well, $n. We may need you fighting by our side before the next moon fills.' WHERE `Id` = 49684;
UPDATE `broadcast_text` SET `Text` = 'Leave that to me.' WHERE `Id` = 49691;
UPDATE `broadcast_text` SET `Text` = 'This totem has been corrupting the eggs! It seems a greater threat looms. The Gnarlpine remain tainted by something most foul.' WHERE `Id` = 49697;
UPDATE `broadcast_text` SET `Text` = 'Helgrum!' WHERE `Id` = 49699;
UPDATE `broadcast_text` SET `Text` = 'Be strong, Neeka. I will watch over you...' WHERE `Id` = 49704;
UPDATE `broadcast_text` SET `Text` = 'Poor Glubtok.  When his powers manifested, his own ogre mound was the first to burn.' WHERE `Id` = 49715;
UPDATE `broadcast_text` SET `Text` = 'Deep within his soul, the one thing he feared most of all was...himself.' WHERE `Id` = 49716;
