UPDATE `broadcast_text` SET `Text` = 'Come forth, children of twilight....' WHERE `Id` = 49738;
UPDATE `broadcast_text` SET `Text` = 'Your mother calls!' WHERE `Id` = 49739;
UPDATE `broadcast_text` SET `Text` = 'Ripsnarl wasn''t always a bloodthirsty savage.  Once, he even had a family.' WHERE `Id` = 49742;
UPDATE `broadcast_text` SET `Text` = 'He was called James Harrington.  A tragedy in three parts.' WHERE `Id` = 49745;
