UPDATE `broadcast_text` SET `Text` = 'Warlord Kalithresh will fall!' WHERE `Id` = 53121;
UPDATE `broadcast_text` SET `Text` = 'That''s suicide, Claw! It''s too dangerous.' WHERE `Id` = 53124;
UPDATE `broadcast_text` SET `Text` = 'There''s too many of them. Kalithresh has an entire army down here.' WHERE `Id` = 53137;
UPDATE `broadcast_text` SET `Text` = 'How can I help you?' WHERE `Id` = 53140;
UPDATE `broadcast_text` SET `Text` = 'How can I help you?' WHERE `Id` = 53146;
UPDATE `broadcast_text` SET `Text` = 'There is nothing left for you here, nothing but death and sorrow.' WHERE `Id` = 53147;
UPDATE `broadcast_text` SET `Text` = 'The darkness surrounds you, the light of Elune is your only salvation.' WHERE `Id` = 53148;
UPDATE `broadcast_text` SET `Text` = 'The moonlight can bring rest to your weary souls in this forgotten place.' WHERE `Id` = 53149;
UPDATE `broadcast_text` SET `Text` = 'Give yourselves to the night, Elune will guide you from this mortal prison.' WHERE `Id` = 53150;
UPDATE `broadcast_text` SET `Text` = 'You have chosen a path of darkness.  Mother moon, guide my hand; allow me to bring rest to these misbegotten souls.' WHERE `Id` = 53151;
