UPDATE `broadcast_text` SET `Text` = '...Ji, they were in the Wood of Staves.  You know where Master Shang is now.' WHERE `Id` = 55555;
UPDATE `broadcast_text` SET `Text` = 'Hey! Look at that waterfall!' WHERE `Id` = 55557;
UPDATE `broadcast_text` SET `Text` = 'I wonder if there''s a cave behind it.' WHERE `Id` = 55558;
