UPDATE `broadcast_text` SET `Text` = 'Ji, be respectful when we speak to Shen-zin Su.' WHERE `Id` = 55560;
UPDATE `broadcast_text` SET `Text` = 'I might if you embarrass us.' WHERE `Id` = 55562;
UPDATE `broadcast_text` SET `Text` = 'Shen-zin Su, we are the descendants of Liu Lang.  We''ve sensed your pain, and we want to help.' WHERE `Id` = 55563;
