UPDATE `broadcast_text` SET `Text` = 'Check out all the cool silk!' WHERE `Id` = 55565;
UPDATE `broadcast_text` SET `Text` = 'Do you think that they really get this stuff from the silkworms'' rear end?' WHERE `Id` = 55566;
UPDATE `broadcast_text` SET `Text` = 'Eww... they look like maggots.' WHERE `Id` = 55567;
UPDATE `broadcast_text` SET `Text` = 'Of course, Shen-zin Su!  But your shell is large, and I do not know where this thorn could be.' WHERE `Id` = 55571;
UPDATE `broadcast_text` SET `Text` = 'We will find it, and we will remove it.  You have our word!' WHERE `Id` = 55573;
UPDATE `broadcast_text` SET `Text` = 'We''ll know soon enough.' WHERE `Id` = 55576;
