UPDATE `broadcast_text` SET `Text` = 'We should let Elder Shaopai know and then plan our next move.' WHERE `Id` = 55582;
UPDATE `broadcast_text` SET `Text` = 'Look at this!' WHERE `Id` = 55583;
UPDATE `broadcast_text` SET `Text` = 'There''s a village up here... and a big fish statue, too.' WHERE `Id` = 55584;
UPDATE `broadcast_text` SET `Text` = 'You think the jinyu built this place?' WHERE `Id` = 55585;
UPDATE `broadcast_text` SET `Text` = 'I suppose that''s enough for today. Let''s wait for Uncle Chen to return.' WHERE `Id` = 55593;
UPDATE `broadcast_text` SET `Text` = 'Look, here he comes now! How was the brewery, Uncle?' WHERE `Id` = 55594;
UPDATE `broadcast_text` SET `Text` = 'Swagger all you like; you pups don''t stand a chance. Flee now, while you can.' WHERE `Id` = 55646;
