UPDATE `broadcast_text` SET `Text` = 'You should have run, dog.' WHERE `Id` = 55648;
UPDATE `broadcast_text` SET `Text` = 'Feh!' WHERE `Id` = 55649;
UPDATE `broadcast_text` SET `Text` = 'Down, pup.' WHERE `Id` = 55650;
UPDATE `broadcast_text` SET `Text` = 'A waste of my time.' WHERE `Id` = 55651;
UPDATE `broadcast_text` SET `Text` = 'Stay, pup.' WHERE `Id` = 55652;
UPDATE `broadcast_text` SET `Text` = 'Hold still.' WHERE `Id` = 55653;
UPDATE `broadcast_text` SET `Text` = 'You can''t outrun the storm.' WHERE `Id` = 55654;
UPDATE `broadcast_text` SET `Text` = 'Die beneath the ice.' WHERE `Id` = 55655;
UPDATE `broadcast_text` SET `Text` = 'Suffer the storm''s wrath!' WHERE `Id` = 55656;
UPDATE `broadcast_text` SET `Text` = 'Thunder and lightning dance at my call!' WHERE `Id` = 55657;
UPDATE `broadcast_text` SET `Text` = 'You face more than my axes, this close.' WHERE `Id` = 55658;
UPDATE `broadcast_text` SET `Text` = 'See what becomes of those who stand before me!' WHERE `Id` = 55659;
UPDATE `broadcast_text` SET `Text` = 'Feel a chill up your spine...?' WHERE `Id` = 55660;
