UPDATE `broadcast_text` SET `Text` = 'I''ll finish you now, pups!' WHERE `Id` = 55674;
UPDATE `broadcast_text` SET `Text` = 'Another stranger? Where are all of you coming from?$b$BSomeone was through here a few days ago claiming to be from the turtle. Said his name was Stormstout.' WHERE `Id` = 55712;
UPDATE `broadcast_text` SET `Text` = 'You''re not here to start a fight in my brewery are you? Those two strangers over there started quite a brawl when they arrived last week.' WHERE `Id` = 55713;
UPDATE `broadcast_text` SET `Text` = 'Lorewalker Cho spoke highly of you. You are welcome as long as you don''t go all hozen on us.' WHERE `Id` = 55714;
UPDATE `broadcast_text` SET `Text` = 'Cowards! You pack of weakling... dogs...' WHERE `Id` = 55715;
UPDATE `broadcast_text` SET `Text` = 'Wow stranger! You really showed that mean old witch who was boss.' WHERE `Id` = 55724;
UPDATE `broadcast_text` SET `Text` = 'It was so neat how you beat up those cats! They went and were like "Grrrrr!" and then you went and "Wabang!" and then you took their stuff.' WHERE `Id` = 55725;
UPDATE `broadcast_text` SET `Text` = 'The grown ups always told us the Jade Witch was just some old lady in the woods who was sad her husband died. But you showed them!$b$bOnly... I didn''t tell any of the grown ups ''cause I didn''t want to get in trouble.' WHERE `Id` = 55726;
UPDATE `broadcast_text` SET `Text` = 'Do you seek enlightenment?' WHERE `Id` = 55730;
