UPDATE `broadcast_text` SET `Text` = 'The link to the portal must be broken! Quickly, to Stormrage!' WHERE `Id` = 55918;
UPDATE `broadcast_text` SET `Text` = 'Ah, welcome. You are here to join us in the coming celebration? No? A pity.' WHERE `Id` = 55919;
UPDATE `broadcast_text` SET `Text` = 'Serve Azshara, puppets, and rejoice.' WHERE `Id` = 55920;
UPDATE `broadcast_text` SET `Text` = 'Such insolence. My temper grows short.' WHERE `Id` = 55922;
UPDATE `broadcast_text` SET `Text` = 'Pshh... outsiders. You know nothing about the Stoneplow way.' WHERE `Id` = 55929;
UPDATE `broadcast_text` SET `Text` = 'We''re proud. We''re strong. We are descended from the blood of the Tiller himself... and we don''t run from trouble.' WHERE `Id` = 55930;
UPDATE `broadcast_text` SET `Text` = 'Oh, honey...' WHERE `Id` = 55936;
UPDATE `broadcast_text` SET `Text` = 'Daddy, is this nice person going to kill all the bad mantid soldiers?' WHERE `Id` = 55937;
UPDATE `broadcast_text` SET `Text` = 'Those had better not be evacuation papers I see.' WHERE `Id` = 55947;
UPDATE `broadcast_text` SET `Text` = 'Welcome to Stoneplow. What can we do for you?' WHERE `Id` = 55948;
UPDATE `broadcast_text` SET `Text` = 'I apologize for the mess. Things are a little hectic right now.$b$bHow can I be of service to you?' WHERE `Id` = 55949;
