UPDATE `broadcast_text` SET `Text` = 'WHAT? FOLLOW YOU? OKAY!' WHERE `Id` = 55976;
UPDATE `broadcast_text` SET `Text` = 'Did you hear that!? The Hidden Master, to the north of here!?' WHERE `Id` = 55992;
