UPDATE `broadcast_text` SET `Text` = 'A little ice ought to quench the fire in your hearts...' WHERE `Id` = 56579;
UPDATE `broadcast_text` SET `Text` = 'Why won''t you give up?!' WHERE `Id` = 56580;
