UPDATE `broadcast_text` SET `Text` = 'Don''t preen just yet, little pups. We''ll cleanse this world of your kind.' WHERE `Id` = 56615;
UPDATE `broadcast_text` SET `Text` = 'You''ll not leave this place alive!' WHERE `Id` = 56616;
