UPDATE `broadcast_text` SET `Text` = 'By the very edge...' WHERE `Id` = 56621;
UPDATE `broadcast_text` SET `Text` = 'I do not know who you are, but I thank you. Without your aid, our world would be...I do not wish to think about it. Moon goddess light your path.' WHERE `Id` = 56622;
