UPDATE `broadcast_text` SET `Text` = 'Then truly, we are lost.' WHERE `Id` = 56668;
UPDATE `broadcast_text` SET `Text` = 'I sense danger...it is a trap...carefully laid for us at this crucial moment.' WHERE `Id` = 56669;
UPDATE `broadcast_text` SET `Text` = 'Gather your courage, $r. Together, we can resist the sha.' WHERE `Id` = 56684;
UPDATE `broadcast_text` SET `Text` = 'When the sha attack began, every one of my students ran to battle without hesitation.$B$BI have taught them much, but yet they continue to surpass my expectations.' WHERE `Id` = 56685;
UPDATE `broadcast_text` SET `Text` = 'Much of our knowledge of the sha has been lost through time.$B$BWhile the battle continues, I must study their nature.$B$BOnly then can we prevent this from happening again in the future.' WHERE `Id` = 56686;
