UPDATE `broadcast_text` SET `Text` = 'Do not give up hope, friends!' WHERE `Id` = 56718;
UPDATE `broadcast_text` SET `Text` = 'Tomorrow, they will sing our praises, but only if we are victorious today.' WHERE `Id` = 56719;
UPDATE `broadcast_text` SET `Text` = 'Be at peace, child.' WHERE `Id` = 56725;
UPDATE `broadcast_text` SET `Text` = 'Your sacrifice will not be forgotten.' WHERE `Id` = 56726;
UPDATE `broadcast_text` SET `Text` = 'Deathwing will pay for this.' WHERE `Id` = 56727;
