UPDATE `broadcast_text` SET `Text` = 'Thank you, sisters, I am renewed.' WHERE `Id` = 56741;
UPDATE `broadcast_text` SET `Text` = 'The Old Gods have shown themselves - a tide of darkness sweeps from their gaping maws towards the temple. We MUST buy the aspects more time.' WHERE `Id` = 56742;
UPDATE `broadcast_text` SET `Text` = 'The faceless generals, Zon''ozz and Yor''sahj, command the enemy legions from within the monstrosities you see on the horizon.' WHERE `Id` = 56743;
