UPDATE `broadcast_text` SET `Text` = 'Not so tough now, are you? That''s right. You look so dumb there laying on the ground. Don''t make me make $p throw more barrels at you.' WHERE `Id` = 56801;
UPDATE `broadcast_text` SET `Text` = 'Oh thank you hero! You have given us a great gift!' WHERE `Id` = 56823;
UPDATE `broadcast_text` SET `Text` = 'One thing I have learned from the sha. They know how to prey on our weaknesses.' WHERE `Id` = 56825;
