UPDATE `broadcast_text` SET `Text` = 'Well this wagon ain''t gonna fix itself.' WHERE `Id` = 58672;
UPDATE `broadcast_text` SET `Text` = 'Look, here''s the deal. You keep yammerin'' and I stop hammerin''.' WHERE `Id` = 58673;
UPDATE `broadcast_text` SET `Text` = 'I got a green thumb and a steel thumb. My pappy taught me how to fix just ''bout anything.' WHERE `Id` = 58674;
