UPDATE `broadcast_text` SET `Text` = 'Greetings, traveler. Welcome to The Golden Lantern!' WHERE `Id` = 64892;
UPDATE `broadcast_text` SET `Text` = 'Rest your weary feet, $r. Fine food and drink await you within.' WHERE `Id` = 64893;
UPDATE `broadcast_text` SET `Text` = 'Oh, you are looking too thin, $r. You must have something to eat. Sit and I will get you something.' WHERE `Id` = 64894;
