UPDATE `broadcast_text` SET `Text` = 'Down! Everybody down!' WHERE `Id` = 71708;
UPDATE `broadcast_text` SET `Text` = 'Champion, are you all right?' WHERE `Id` = 71709;
UPDATE `broadcast_text` SET `Text` = 'They were ready for us all along. Our forces are scattered, and we are on our own.' WHERE `Id` = 71710;
UPDATE `broadcast_text` SET `Text` = 'So much for the element of surprise.' WHERE `Id` = 71711;
UPDATE `broadcast_text` SET `Text` = 'They are falling back! We need to press the assault before they can regroup. Follow me!' WHERE `Id` = 71712;
UPDATE `broadcast_text` SET `Text` = 'As I always say - Victory to the bold!' WHERE `Id` = 71713;
UPDATE `broadcast_text` SET `Text` = 'The entrance is barricaded. Break it down!' WHERE `Id` = 71714;
UPDATE `broadcast_text` SET `Text` = 'Be quick on your feet - that is no ordinary Zandalari!' WHERE `Id` = 71715;
UPDATE `broadcast_text` SET `Text` = 'They are protecting that mask. It must be the source of the barrier. Destroy it!' WHERE `Id` = 71716;
UPDATE `broadcast_text` SET `Text` = 'Destroy the spirit mask to bring down the barrier!' WHERE `Id` = 71717;
UPDATE `broadcast_text` SET `Text` = 'He''s protecting the mask. Kill him!' WHERE `Id` = 71718;
UPDATE `broadcast_text` SET `Text` = 'Keep it up, they are beginning to rout!' WHERE `Id` = 71719;
UPDATE `broadcast_text` SET `Text` = 'The shield - it is down! We did it!' WHERE `Id` = 71720;
UPDATE `broadcast_text` SET `Text` = 'Jaina was right to recommend you. You saved this mission from disaster... and saved my life.' WHERE `Id` = 71721;
UPDATE `broadcast_text` SET `Text` = 'That''s the Alliance spirit for you - unstoppable!' WHERE `Id` = 71722;
UPDATE `broadcast_text` SET `Text` = 'Vereesa, establish a perimeter. Modera, place the sentry wards. Narasi, begin porting in tents and supplies.' WHERE `Id` = 71723;
UPDATE `broadcast_text` SET `Text` = 'Everyone take up positions! Enemies surround us on all sides! There is no time to waste.' WHERE `Id` = 71724;
UPDATE `broadcast_text` SET `Text` = 'Champion, you have exceeded my expectations. Our position on the isle is secured, thanks to your courage and your will. Now, the true work begins.' WHERE `Id` = 71725;
