UPDATE `broadcast_text` SET `Text` = 'As much as I expected from a troll.' WHERE `Id` = 71727;
UPDATE `broadcast_text` SET `Text` = 'In the name of the Kirin Tor!' WHERE `Id` = 71728;
UPDATE `broadcast_text` SET `Text` = 'I like your style, hero.' WHERE `Id` = 71729;
UPDATE `broadcast_text` SET `Text` = 'Impressive!' WHERE `Id` = 71730;
