UPDATE `broadcast_text` SET `Text` = 'Through you, is it? I think we can manage that.' WHERE `Id` = 71856;
UPDATE `broadcast_text` SET `Text` = 'Would you prefer we go through the belly, or the ribcage?' WHERE `Id` = 71857;
