UPDATE `broadcast_text` SET `Text` = 'They have undermined EVERY attempt at peace!' WHERE `Id` = 71933;
UPDATE `broadcast_text` SET `Text` = 'Jaina takes a deep breath.' WHERE `Id` = 71937;
UPDATE `broadcast_text` SET `Text` = 'My Lord!' WHERE `Id` = 71940;
UPDATE `broadcast_text` SET `Text` = 'Very well. We will stand down.' WHERE `Id` = 71942;
UPDATE `broadcast_text` SET `Text` = 'They killed my husband!' WHERE `Id` = 71943;
UPDATE `broadcast_text` SET `Text` = 'This won''t bring him back.' WHERE `Id` = 71944;
UPDATE `broadcast_text` SET `Text` = 'But know this, "Blood" Elf: There can be no peace while Hellscream is Warchief of the Horde.' WHERE `Id` = 71945;
UPDATE `broadcast_text` SET `Text` = 'Jaina''s expression softens.' WHERE `Id` = 71947;
UPDATE `broadcast_text` SET `Text` = 'Lord.' WHERE `Id` = 71948;
UPDATE `broadcast_text` SET `Text` = 'Everyone, regroup back at the camp. Our work here is done.' WHERE `Id` = 71951;
UPDATE `broadcast_text` SET `Text` = 'Lord Zhu!' WHERE `Id` = 71952;
UPDATE `broadcast_text` SET `Text` = 'We must get you back to the monastery.' WHERE `Id` = 71954;
UPDATE `broadcast_text` SET `Text` = 'Yalia, take Lord Zhu to safety.' WHERE `Id` = 71956;
UPDATE `broadcast_text` SET `Text` = 'Hero, it will be up to you to defeat the Storm Lord Nalak. You will have to marshal a small army!' WHERE `Id` = 71957;
UPDATE `broadcast_text` SET `Text` = 'But after what I have seen today, I have faith in you.' WHERE `Id` = 71958;
UPDATE `broadcast_text` SET `Text` = 'It has been a great honor to fight by your side. Thank you.' WHERE `Id` = 71959;
UPDATE `broadcast_text` SET `Text` = 'You''ve earned my trust hero. Simply place my staff on the Thunder King''s dais and it will do the rest. You are very brave to take this mission on; good luck!' WHERE `Id` = 71960;
UPDATE `broadcast_text` SET `Text` = 'You did it! Incredible! Pandaren Lorewalkers will be telling your story for generations!' WHERE `Id` = 71961;
UPDATE `broadcast_text` SET `Text` = 'I can feel it ... the Thunder King''s power courses through my staff.' WHERE `Id` = 71962;
UPDATE `broadcast_text` SET `Text` = 'Best of all, you''ve forever disabled his infernal machine, leaving nothing for the Horde to claim as their own.' WHERE `Id` = 71963;
UPDATE `broadcast_text` SET `Text` = 'When the time is right, I''ll use this staff to bring the walls of Orgrimmar crashing down around Garrosh Hellscream''s head.' WHERE `Id` = 71964;
UPDATE `broadcast_text` SET `Text` = 'Thank you, friend. The Alliance is lucky to have you.' WHERE `Id` = 71965;
UPDATE `broadcast_text` SET `Text` = 'A new land overrun by evil horrors of this world. A new place for us to save.' WHERE `Id` = 72000;
