UPDATE `broadcast_text` SET `Text` = 'They will learn that no place is safe from the Shado-Pan.' WHERE `Id` = 72063;
UPDATE `broadcast_text` SET `Text` = 'I prefer a swift, silent kill. But your methods have their advantages.' WHERE `Id` = 72064;
