UPDATE `broadcast_text` SET `Text` = 'This way - the Zandalari are falling back!' WHERE `Id` = 72718;
UPDATE `broadcast_text` SET `Text` = 'Through the breech! Focus on their priests - they''re empowering the others!' WHERE `Id` = 72719;
UPDATE `broadcast_text` SET `Text` = 'By the light - what did they DO to that thing?' WHERE `Id` = 72720;
