UPDATE `broadcast_text` SET `Text` = 'I''ve been in the middle of a few messes in my day, but this is ridiculous!' WHERE `Id` = 73654;
UPDATE `broadcast_text` SET `Text` = 'We just need to stay focused on our mission so we can get out of here in one piece.' WHERE `Id` = 73655;
