UPDATE `broadcast_text` SET `Text` = 'Ever wonder what we do with all our obsolete robots? We send them to their deaths in bloody gladiatorial arenas, of course! Here comes Blingtron 3000!' WHERE `Id` = 73729;
UPDATE `broadcast_text` SET `Text` = 'He''s never seen an opponent that he wouldn''t fight. Ah, small correction: he''s never seen an opponent. He''s the Blind Hero!' WHERE `Id` = 73730;
UPDATE `broadcast_text` SET `Text` = 'Ah, the dragon child and the hero. Together you will achieve great things.' WHERE `Id` = 73748;
UPDATE `broadcast_text` SET `Text` = 'Tell me, dragon child: What is the nature of wisdom?' WHERE `Id` = 73749;
UPDATE `broadcast_text` SET `Text` = 'Spoken like a true child of the Aspects. Always seeking to change the world.' WHERE `Id` = 73750;
UPDATE `broadcast_text` SET `Text` = 'But true wisdom comes from KNOWING what is right. And sometimes, DOING nothing at all.' WHERE `Id` = 73751;
UPDATE `broadcast_text` SET `Text` = 'To learn THAT is to learn true wisdom.' WHERE `Id` = 73752;
UPDATE `broadcast_text` SET `Text` = 'Come forward! I will give you my blessing.' WHERE `Id` = 73753;
UPDATE `broadcast_text` SET `Text` = 'My challenge, if you accept it, will test your cunning and footwork even in the midst of life-threatening danger.' WHERE `Id` = 73754;
