UPDATE `broadcast_text` SET `Text` = 'Use movement to your advantage. Do not allow the dragon child to get close.' WHERE `Id` = 73770;
UPDATE `broadcast_text` SET `Text` = 'Be aware of your surroundings.' WHERE `Id` = 73771;
UPDATE `broadcast_text` SET `Text` = 'Do not allow the elements to engage you!' WHERE `Id` = 73772;
UPDATE `broadcast_text` SET `Text` = 'That is enough!' WHERE `Id` = 73779;
UPDATE `broadcast_text` SET `Text` = 'Champion, predict your foe''s movements, and always stay a step ahead. Victory is within you!' WHERE `Id` = 73780;
UPDATE `broadcast_text` SET `Text` = 'Very good - that is enough!' WHERE `Id` = 73781;
UPDATE `broadcast_text` SET `Text` = 'Do you see? Power without vision causes only random chaos and destruction.' WHERE `Id` = 73783;
UPDATE `broadcast_text` SET `Text` = 'Seek out your true enemy! Do not be fooled by his false images!' WHERE `Id` = 73880;
UPDATE `broadcast_text` SET `Text` = 'The elements are undying! Make use of your time before they rise again!' WHERE `Id` = 73881;
UPDATE `broadcast_text` SET `Text` = 'Please, young prince. Take this lesson to heart.' WHERE `Id` = 73882;
