UPDATE `broadcast_text` SET `Text` = 'Tortured wind, stale and toxic!' WHERE `Id` = 76936;
UPDATE `broadcast_text` SET `Text` = 'Long-dead fire, black and smouldering!' WHERE `Id` = 76937;
UPDATE `broadcast_text` SET `Text` = 'I can hear them no longer...' WHERE `Id` = 76939;
UPDATE `broadcast_text` SET `Text` = 'My wolf will feast on your blood!' WHERE `Id` = 76940;
