UPDATE `broadcast_text` SET `Text` = 'I want to train him, but I really don''t want him to get hurt.' WHERE `Id` = 76969;
UPDATE `broadcast_text` SET `Text` = 'He''s really nice and he tries to cook things for me. Unfortunately, they aren''t edible and I have to toss them out when he isn''t looking.' WHERE `Id` = 76970;
UPDATE `broadcast_text` SET `Text` = 'Now is my chance!' WHERE `Id` = 76988;
UPDATE `broadcast_text` SET `Text` = 'I''ve never seen anything quite like this!  I think I''ll be healing a lot of pets after the tournament is over.' WHERE `Id` = 77002;
